(() => {
  'use strict';
  const propertyHost = 'gulplaj-hotel.hotelrunner.com';
  let ready = false, scheduled = false;
  const notice = document.getElementById('widget-loading');
  function send(state) {
    if (window.parent === window) return;
    // Measure normal content rather than viewport scrollHeight, so the frame
    // shrinks again after closing a calendar or guest menu.
    let height = Math.max(150, document.body.getBoundingClientRect().height);
    document.querySelectorAll('.datepicker,.dropdown-menu').forEach(element => {
      const style = getComputedStyle(element);
      if (style.display !== 'none' && style.visibility !== 'hidden') {
        height = Math.max(height, element.getBoundingClientRect().bottom + window.scrollY + 24);
      }
    });
    window.parent.postMessage({type:'gulplaj:hotelrunner',state,height:Math.ceil(height)}, location.origin);
  }
  function refresh() {
    scheduled = false;
    const available = Boolean(document.getElementById('hr_booking_button'));
    if (available && !ready) {
      ready = true;
      notice.hidden = true;
      document.documentElement.style.setProperty('--widget-color','#143b4a');
      // Leave the isolated search frame for the secure, full-page booking flow.
      window.open_how = '_top';
      window.HotelRunnerWidget = secureTransport;
      const dateInput = document.getElementById('check_in_out');
      const guestButton = document.getElementById('dropdown_toggle');
      for (const [control, text] of [[dateInput,'Giriş · Çıkış tarihi'],[guestButton,'Oda ve misafirler']]) {
        if (!control) continue;
        const label = document.createElement('label');
        label.className = 'search-field-label';
        label.htmlFor = control.id;
        label.textContent = text;
        control.closest('.outer_input').prepend(label);
      }
      if (dateInput) dateInput.addEventListener('keydown',event=>{
        if (event.key === 'Enter' || event.key === ' ') {event.preventDefault();dateInput.click();}
      });
      const searchButton = document.getElementById('hr_booking_button');
      searchButton.textContent = 'Fiyat ve müsaitlik ara  →';
      searchButton.setAttribute('aria-label','Seçilen tarihler ve misafirler için fiyat ve müsaitlik ara');
    }
    send(ready ? 'ready' : 'loading');
  }
  function schedule() {
    if (scheduled) return;
    scheduled = true;
    requestAnimationFrame(refresh);
  }
  // HotelRunner replaces its mounting div, so watch the enclosing document.
  new MutationObserver(schedule).observe(document.body, {childList:true,subtree:true,attributes:true});
  if ('ResizeObserver' in window) new ResizeObserver(schedule).observe(document.body);
  window.addEventListener('load', schedule);
  window.addEventListener('resize', schedule);
  document.addEventListener('click', schedule);
  // HotelRunner's supplied widget uses this hook on HTTP (including local QA).
  // The destination is generated by HotelRunner; do not synthesize rate/guest parameters.
  const secureTransport = Object.freeze({show(value) {
    try {
      const url = new URL(value);
      if (url.protocol !== 'https:' || url.hostname !== propertyHost || url.username || url.password) return;
      window.top.location.assign(url.href);
    } catch { /* Keep the direct booking link available in the parent. */ }
  }});
  window.HotelRunnerWidget = secureTransport;
  setTimeout(() => {
    if (!ready) {
      notice.textContent = 'Arama modülü yüklenemedi. Aşağıdaki rezervasyon bağlantısıyla devam edebilirsiniz.';
      send('unavailable');
    }
  }, 20000);
})();
